module prime_minister_happy (\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] num_cities,\n    input [4:0] K,\n    input [7:0] x0, x1, x2, x3,\n    input [7:0] y0, y1, y2, y3,\n    input [7:0] pop0, pop1, pop2, pop3,\n    output reg [23:0] sq_dist_result,\n    output reg done\n);\n    // State definitions\n    localparam [3:0] IDLE             = 4'd0;\n    localparam [3:0] COMPUTE_DIST     = 4'd1;\n    localparam [3:0] SORT_DIST        = 4'd2;\n    localparam [3:0] INIT_GRAPH       = 4'd3;\n    localparam [3:0] ADD_EDGES        = 4'd4;\n    localparam [3:0] FIND_COMPONENTS  = 4'd5;\n    localparam [3:0] CHECK_SUBSET     = 4'd6;\n    localparam [3:0] UPDATE_RESULT    = 4'd7;\n    localparam [3:0] DONE             = 4'd8;\n    \n    // Internal registers\n    reg [3:0] state, next_state;\n    reg [17:0] dist_array [0:5];  // 6 possible distances (18 bits)\n    reg [17:0] sorted_dist [0:5];\n    reg [3:0] num_valid_dists;    // Actual number based on num_cities\n    reg [2:0] dist_idx;           // Distance processing index\n    reg [2:0] edge_count;\n    reg [3:0] city_present [0:3];\n    reg [17:0] current_sq_dist;\n    \n    // DFS and DP variables\n    reg [3:0] component_pop [0:3];  // Population in current component\n    reg [1:0] comp_size;            // Size of current component\n    reg [29:0] dp;                  // Bitmask for subset sum mod K (0..29)\n    reg [1:0] pop_count, comp_idx;\n    reg found_subset;\n    \n    // Union-find variables\n    reg [1:0] parent [0:3];\n    reg [1:0] rank [0:3];\n    reg [1:0] root_nodes [0:3];\n    reg [1:0] comp_search_idx;\n    reg [7:0] cycle_counter;\n    \n    integer i, j;  // Loop counters\n    \n    // Function to compute squared distance\n    function automatic [17:0] calculate_sq_dist;\n        input [7:0] x1, y1, x2, y2;\n        reg [8:0] dx, dy;\n        begin\n            dx = x1 - x2;\n            dy = y1 - y2;\n            calculate_sq_dist = dx*dx + dy*dy;\n        end\n    endfunction\n    \n    // Function to find root in union-find\n    function automatic [1:0] find_root;\n        input [1:0] node;\n        begin\n            find_root = (parent[node] == node) ? node : find_root(parent[node]);\n        end\n    endfunction\n    \n    // State machine and main logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            for (i = 0; i < 6; i = i + 1) begin\n                dist_array[i] <= 18'd0;\n                sorted_dist[i] <= 18'd0;\n            end\n            for (i = 0; i < 4; i = i + 1) begin\n                city_present[i] <= (i < num_cities);\n                parent[i] <= (i < 2'd3) ? i[1:0] : 2'd0;\n                rank[i] <= 2'd0;\n                component_pop[i] <= 4'd0;\n            end\n            sq_dist_result <= 24'd0;\n            done <= 1'b0;\n            num_valid_dists <= 4'd0;\n            dist_idx <= 3'd0;\n            edge_count <= 3'd0;\n            current_sq_dist <= 18'd0;\n            dp <= 30'd0;\n            found_subset <= 1'b0;\n            comp_size <= 2'd0;\n            pop_count <= 2'd0;\n            comp_idx <= 2'd0;\n            comp_search_idx <= 2'd0;\n            cycle_counter <= 8'd0;\n        end else begin\n            cycle_counter <= cycle_counter + 8'd1;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= COMPUTE_DIST;\n                        num_valid_dists <= (num_cities * (num_cities - 1)) >> 1;\n                        // Mark present cities\n                        for (i = 0; i < 4; i = i + 1) begin\n                            city_present[i] <= (i < num_cities);\n                        end\n                    end\n                end\n                \n                COMPUTE_DIST: begin\n                    // Compute all pairwise distances between present cities\n                    // Only compute when city_present[i] and city_present[j]\n                    dist_array[0] <= calculate_sq_dist(x0, y0, x1, y1);\n                    dist_array[1] <= calculate_sq_dist(x0, y0, x2, y2);\n                    dist_array[2] <= calculate_sq_dist(x0, y0, x3, y3);\n                    dist_array[3] <= calculate_sq_dist(x1, y1, x2, y2);\n                    dist_array[4] <= calculate_sq_dist(x1, y1, x3, y3);\n                    dist_array[5] <= calculate_sq_dist(x2, y2, x3, y3);\n                    state <= SORT_DIST;\n                end\n                \n                SORT_DIST: begin\n                    // Bubble sort implementation\n                    if (dist_idx >= num_valid_dists - 1) begin\n                        dist_idx <= 3'd0;\n                        state <= INIT_GRAPH;\n                    end else begin\n                        for (j = 0; j < num_valid_dists - dist_idx - 1; j = j + 1) begin\n                            if (dist_array[j] > dist_array[j+1]) begin\n                                // Swap\n                                dist_array[j] <= dist_array[j+1];\n                                dist_array[j+1] <= dist_array[j];\n                            end\n                        end\n                        dist_idx <= dist_idx + 3'd1;\n                    end\n                end\n                \n                INIT_GRAPH: begin\n                    // Initialize union-find structure\n                    for (i = 0; i < 4; i = i + 1) begin\n                        parent[i] <= city_present[i] ? i[1:0] : 2'd0;\n                        rank[i] <= 2'd0;\n                    end\n                    edge_count <= 3'd0;\n                    current_sq_dist <= dist_array[0];\n                    dist_idx <= 3'd0;\n                    state <= ADD_EDGES;\n                end\n                \n                ADD_EDGES: begin\n                    if (dist_idx < num_valid_dists && dist_array[dist_idx] <= current_sq_dist) begin\n                        // Union nodes for this edge\n                        // Find roots and union (implementation omitted for brevity)\n                        dist_idx <= dist_idx + 3'd1;\n                        edge_count <= edge_count + 3'd1;\n                    end else begin\n                        state <= FIND_COMPONENTS;\n                    end\n                    if (cycle_counter > 8'd200) state <= UPDATE_RESULT;  // Timeout\n                end\n                \n                FIND_COMPONENTS: begin\n                    // Find root of each node and collect root components\n                    // (Implementation steps for collecting components omitted)\n                    comp_search_idx <= 2'd0;\n                    comp_size <= 2'd0;\n                    state <= CHECK_SUBSET;\n                end\n                \n                CHECK_SUBSET: begin\n                    if (comp_search_idx < num_cities) begin\n                        // For each component (collected in FIND_COMPONENTS):\n                        if (component_pop[pop_count]) begin\n                            // DP update logic for subset sum modulo K\n                            dp <= dp | (dp << component_pop[pop_count]) | (30'd1 << component_pop[pop_count]);\n                            pop_count <= pop_count + 2'd1;\n                        end\n                        // Check if dp[0] is set\n                        found_subset <= dp[0];\n                    end else begin\n                        if (found_subset) begin\n                            state <= UPDATE_RESULT;\n                        end else begin\n                            current_sq_dist <= dist_array[dist_idx];\n                            dist_idx <= dist_idx + 3'd1;\n                            if (dist_idx < num_valid_dists) begin\n                                state <= ADD_EDGES;\n                            end else begin\n                                state <= UPDATE_RESULT;\n                            end\n                        end\n                    end\n                end\n                \n                UPDATE_RESULT: begin\n                    sq_dist_result <= {6'd0, current_sq_dist};\n                    state <= DONE;\n                end\n                \n                DONE: begin\n                    done <= 1'b1;\n                    if (!start) state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule